package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
import org.jlinalg.cli.CiceroWorkflowRequest.Request;

/** Typed original Cicero co-accessibility with native complete-population audits and atomic admission. */
public final class CiceroWorkflowCli {
    private CiceroWorkflowCli() { }
    static final String SCOPE="Original Cicero-Monocle3 1.3.9 co-accessibility from explicit raw counts, peak/cell metadata, caller-prepared coordinates and genome lengths. Original input ordering, cell aggregation, size factors, distance calibration, graphical-lasso fits and connection assembly remain upstream and are retained. Native Java independently checks literal axes/parser mapping, selected k-nearest neighborhoods with ties, count aggregation/normalization, numeric summaries, strict endpoint windows, covariance/penalty inputs, model shape/error flags and every ordered connection/signed reconciliation. R RNG, FNN tie selection, distance fitting and glasso optimization are not independently refitted/authenticated. Source NA from disagreeing windows remains distinct from zero and absence. No graph embedding is inferred. Exact selected versions and R bodies/formals are checked, not every dependency/native DLL. CCANs, gene activities, paper-specific shuffled background/FDR and historical paper environments are not implied. Logical limits are not OS quotas; output limit bounds worker growth before admitted copies.";
    static final String ACTION="Read WARNINGS.md, analysis-status.json, worker/worker-report.json, worker/cases/ID/source-status.json and original stdout/stderr; require result_admitted=true. SKIP3: supply the exact permitted Windows Java/R4.6.1/private Cicero1.3.9/Monocle3 1.4.27 profile or skip dependent analysis. Analysis installs nothing and substitutes no version. FAIL2: no result of a failed atomic batch is admitted, including earlier completed cases. Preserve raw source dispositions, original errors, warnings, NA/NaN/Inf and all objects. Correct the named input/model/runtime/policy/capacity cause and retry NEW paths without dropping peaks/cells, identifier/value repair, imputation or NA-to-zero substitution. Four unresolved NA connections in the reference control are not four valid nulls. No portable VERIFY request is provided.";
    private record Captured(Path original,Path copy,NextflowFiles.Pin pin){void verify()throws IOException{require(pin.equals(NextflowFiles.pin(original,pin.bytes(),()->{}))&&pin.equals(NextflowFiles.pin(copy,pin.bytes(),()->{})),"Original/captured input changed: "+original);}}
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(output,"java -cp DEVELOPMENT.jar org.jlinalg.cli.CiceroWorkflowCli --request ASCII_PATH.json\nRequire schema_version1, mode COACCESS, exact version, count_units raw-integer-counts, matrix_format dense-tsv/matrix-market, coordinate_system one-based-closed/zero-based-half-open, counts/peak_metadata/cell_metadata/embedding/genome paths, numeric_metadata, binarize, analyses, NEW out and explicit rscript/r_home/r_libraries.\nPeak metadata: peak_id chromosome start end. IDs encode their exact endpoints using original : - or _ separators. Cell metadata: cell_id plus declared numeric columns. Dense counts: peak_id then cell IDs, with ordered metadata axes. Sparse Matrix Market: general integer/real coordinates, no duplicate coordinates or implicit aggregation. Embedding: cell_id then2..50 dimensions in cell metadata order. Genome: chromosome length; explicit original chromosome normalization is audited, never merged silently.\nEach analysis declares id, aggregation_seed, k, size_factor_normalize, summary_stats, model(window,power,max_elements), distance_parameter, skipped_windows_policy and unresolved_connections_policy. Distance estimate declares seed,maxit,sample_num,distance_constraint,convergence,max_sample_windows,require_full_sample and allow_maxit_warning; fixed mode declares value. No arbitrary scripts, formulas, input RDS or implicit scientific filters.\n"+SCOPE+"\n"+ACTION);return 0;}
            require(args.length==2&&args[0].equals("--request"),"Require --request UTF8_JSON or --help");Path source=Path.of(args[1]).toAbsolutePath().normalize();var pin=NextflowFiles.pin(source,1048576,()->{});byte[] raw=NextflowFiles.bytes(source,1048576);require(pin.bytes()==raw.length&&pin.sha256().equals(NextflowFiles.sha(raw)),"Request changed during intake");Request r=CiceroWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),1048576,100000)),source.getParent());
            var protectedPaths=new ArrayList<Path>(r.libraries());protectedPaths.add(r.rHome());Path out=resolved(r.out());for(Path p:protectedPaths){Path path=resolved(p);require(!out.startsWith(path)&&!path.startsWith(out),"Output cannot overlap R home/libraries, including aliases");}
            int[] exit={0};FollowupSupport.externalTransaction(Map.of("out",r.out().toString()),"original-cicero-coaccessibility-development",(stage,manifest)->{
                var warnings=new ArrayList<String>();warnings.add(SCOPE);var state=new LinkedHashMap<String,Object>();state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("result_admitted",false);
                try{
                    verify(source,pin);Files.write(stage.resolve("source-request.json"),raw,StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(stage.resolve("effective-request.json"),r.effective());Path inputs=Files.createDirectory(stage.resolve("inputs"));var captured=new ArrayList<Captured>();long remaining=r.inputBytes();
                    for(var item:List.of(Map.entry(r.counts(),"counts"),Map.entry(r.peaks(),"peaks.tsv"),Map.entry(r.cells(),"cells.tsv"),Map.entry(r.embedding(),"embedding.tsv"),Map.entry(r.genome(),"genome.tsv"))){var c=capture(item.getKey(),inputs.resolve(item.getValue()),remaining);remaining-=c.pin().bytes();captured.add(c);}
                    var p=CiceroWorkflowInputs.validate(inputs,r);if(p.zeroPeaks()>0)warnings.add("INPUT ZERO-COUNT PEAKS: "+p.zeroPeaks()+" explicitly declared all-zero peaks are retained using zero-valued dimension anchors in the original triplet constructor; no observations are added and no peaks are filtered.");manifest.put("source_request_sha256",pin.sha256());var inputPins=new LinkedHashMap<String,Object>();for(var c:captured)inputPins.put(c.copy().getFileName().toString(),Map.of("bytes",c.pin().bytes(),"sha256",c.pin().sha256()));manifest.put("captured_inputs",inputPins);
                    Path worker=Files.createDirectory(stage.resolve("worker"));NextflowFiles.writeJson(worker.resolve("parameters.json"),r.parameters());CiceroWorkflowRuntime.sources(stage,"1.3.9",false);CiceroWorkflowRuntime.run(stage,r,manifest);diagnostics(CiceroWorkflowAudit.read(worker.resolve("worker-report.json"),r),warnings);
                    for(Captured c:captured)c.verify();verify(source,pin);CiceroWorkflowRuntime.sources(stage,"1.3.9",true);var meter=new CiceroWorkflowAudit.Meter(r.auditOperations());var constructed=CiceroWorkflowAudit.constructed(worker,p,r,meter);var reports=new ArrayList<Map<String,Object>>();
                    for(var a:r.analyses()){
                        var report=CiceroWorkflowAudit.analysis(worker.resolve("cases").resolve(text(a.get("id"))),a,p,constructed,r,meter);reports.add(report);
                        if(((Number)report.get("unresolved_source_NA_retained")).intValue()>0)warnings.add("ORIGINAL UNRESOLVED SCORES ["+a.get("id")+"]: "+report.get("unresolved_source_NA_retained")+" NA connections from disagreeing window signs remain NA; they are not zero, absent interactions or valid nulls.");
                        if(((Number)report.get("original_precision_max_asymmetry")).doubleValue()>0)warnings.add("ORIGINAL PRECISION ASYMMETRY ["+a.get("id")+"]: maximum "+report.get("original_precision_max_asymmetry")+"; raw glasso WI is retained without symmetrization. Connection assembly uses original covariance W. No inverse/solver-convergence certificate is implied.");
                        if(((Number)report.get("source_skipped_windows")).intValue()>0)warnings.add("ORIGINAL SKIPPED WINDOWS ["+a.get("id")+"]: "+report.get("source_skipped_windows")+" source dispositions retained under the explicit request policy; no fictitious models or absence claims.");
                    }
                    Path results=Files.createDirectory(stage.resolve("results"));for(var a:r.analyses())copyTree(worker.resolve("cases").resolve(text(a.get("id"))),results.resolve(text(a.get("id"))));
                    for(Captured c:captured)c.verify();verify(source,pin);CiceroWorkflowRuntime.sources(stage,"1.3.9",true);NextflowFiles.writeJson(stage.resolve("report.json"),Map.of("version",r.version(),"input_peaks",p.peaks().size(),"input_cells",p.cells().size(),"stored_entries",p.storedEntries(),"explicit_zero_entries",p.explicitZeros(),"all_zero_peaks_retained",p.zeroPeaks(),"native_audit_operations",meter.used(),"analyses",reports,"scope",SCOPE,"analysis_installs_software",false));state.put("status","completed-with-warnings");state.put("result_admitted",true);state.put("analyses",reports.size());
                }catch(CiceroWorkflowRuntime.Unavailable failure){exit[0]=3;state.put("status","SKIP3_DEPENDENT_ANALYSIS_SKIPPED");state.put("cause",failure.toString());warnings.add("SKIP3: "+failure);}
                catch(Exception failure){exit[0]=2;state.put("cause",failure.toString());warnings.add("FAIL2: "+failure);}
                catch(OutOfMemoryError failure){exit[0]=2;state.put("cause","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; no partial result admitted. Retry appropriate heap/capacities into NEW paths.");}
                if(exit[0]!=0){if(Files.exists(stage.resolve("results")))Files.move(stage.resolve("results"),stage.resolve("unadmitted-partial-results"));if(Files.exists(stage.resolve("report.json")))Files.move(stage.resolve("report.json"),stage.resolve("unadmitted-report.json"));Path wr=stage.resolve("worker/worker-report.json");if(Files.isRegularFile(wr))try{diagnostics(CiceroWorkflowAudit.read(wr,r),warnings);}catch(IOException failure){warnings.add("Worker diagnostic read failed: "+failure);}}
                state.put("version",r.version());state.put("atomic_batch",true);state.put("required_action",ACTION);NextflowFiles.writeJson(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);manifest.put("analysis_status",state.get("status"));manifest.put("result_admitted",state.get("result_admitted"));manifest.put("scope",SCOPE);
            });
            emit(exit[0]==0?output:error,(exit[0]==0?"Original Cicero analysis completed: ":exit[0]==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO RESULT ADMITTED: ")+r.out());emit(error,"WARNINGS / REQUIRED ACTIONS: "+r.out().resolve("WARNINGS.md")+"\n"+ACTION);return exit[0];
        }catch(Exception failure){emit(error,"FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}catch(OutOfMemoryError failure){emit(error,"FAIL2 NO RESULT ADMITTED: Java heap exhausted. "+ACTION);return 2;}
    }
    private static void diagnostics(Map<String,Object> report,List<String> warnings)throws IOException {for(Object w:list(report.get("warnings")))warnings.add("ORIGINAL R WARNING: "+text(w));for(Object m:list(report.get("messages")))warnings.add("ORIGINAL R MESSAGE: "+text(m));if(!text(report.get("detail")).isEmpty())warnings.add("ORIGINAL R DETAIL: "+text(report.get("detail")));for(Object raw:list(report.get("cases"))){var c=object(raw);for(Object w:list(c.get("warnings")))warnings.add("ORIGINAL R WARNING ["+c.get("id")+"]: "+text(w));for(Object m:list(c.get("messages")))warnings.add("ORIGINAL R MESSAGE ["+c.get("id")+"]: "+text(m));if(c.get("original_error")!=null)warnings.add("ORIGINAL ERROR ["+c.get("id")+"]: "+object(c.get("original_error")));}}
    private static Captured capture(Path original,Path copy,long capacity)throws IOException {require(capacity>=0,"Complete inputs exceed maximum_input_bytes");var pin=NextflowFiles.pin(original,capacity,()->{});long count=0;try(var in=Files.newInputStream(original,LinkOption.NOFOLLOW_LINKS);var out=Files.newOutputStream(copy,StandardOpenOption.CREATE_NEW)){byte[] buffer=new byte[65536];for(int n=in.read(buffer);n>=0;n=in.read(buffer)){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Input capture cancelled");require(n<=capacity-count,"Input grew beyond capacity");out.write(buffer,0,n);count+=n;}}require(count==pin.bytes(),"Input changed during capture");var c=new Captured(original,copy,pin);c.verify();return c;}
    private static void verify(Path path,NextflowFiles.Pin pin)throws IOException {require(pin.equals(NextflowFiles.pin(path,pin.bytes(),()->{})),"Original request changed");}
    private static Path resolved(Path path)throws IOException {var suffix=new ArrayList<Path>();Path ancestor=path;while(ancestor!=null&&!Files.exists(ancestor)){suffix.add(ancestor.getFileName());ancestor=ancestor.getParent();}require(ancestor!=null,"No existing ancestor for output/runtime path");Path result=ancestor.toRealPath();for(int i=suffix.size()-1;i>=0;i--)result=result.resolve(suffix.get(i));return result.normalize();}
    private static void copyTree(Path from,Path to)throws IOException {Files.createDirectory(to);try(var paths=Files.walk(from)){for(Path path:paths.toList()){if(path.equals(from))continue;require(!Files.isSymbolicLink(path),"Refuse result symlink");Path target=to.resolve(from.relativize(path));if(Files.isDirectory(path,LinkOption.NOFOLLOW_LINKS))Files.createDirectory(target);else{require(Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS),"Refuse nonregular result");Files.copy(path,target);}}}}
    private static void emit(PrintStream output,String value){byte[] bytes=(value+"\n").getBytes(StandardCharsets.UTF_8);output.write(bytes,0,bytes.length);output.flush();}
}
